{
  "mode": "single_tool",
  "server": "user-Atlassian",
  "serverStatus": "ready",
  "tool": {
    "tool": "searchJiraIssuesUsingJql",
    "description": "Search issues with JQL, total counts only when explicitly requested.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "cloudId": {
          "type": "string",
          "description": "Cloud ID (UUID or site URL)"
        },
        "jql": {
          "type": "string",
          "description": "JQL query"
        },
        "maxResults": {
          "type": "number",
          "maximum": 100,
          "description": "Max (50-100)"
        },
        "fields": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Issue fields to return. When omitted or empty, defaults to: summary, description, status, issuetype, priority, labels, components, assignee, reporter, created, updated, resolution, project. Pass \"*all\" to return every field (including custom fields). Include \"comment\" to fetch issue comments in fields.comment.comments."
        },
        "nextPageToken": {
          "type": "string",
          "description": "Page token"
        },
        "responseContentFormat": {
          "type": "string",
          "enum": [
            "markdown",
            "adf"
          ],
          "description": "Content format for body content. Use \"markdown\" for simplified plain text. Use \"adf\" (Atlassian Document Format, JSON) for full programmatic fidelity. Defaults vary by tool when omitted."
        },
        "searchResultMode": {
          "type": "string",
          "enum": [
            "issues",
            "count",
            "all"
          ],
          "description": "Default \"issues\". Never count for normal search or if nextPageToken used. If total for same query is known, reuse it. Use \"count\" only when no trusted count exists and either the user asks or a downstream step needs it. Use \"all\" only if both count and issues required."
        }
      },
      "required": [
        "cloudId",
        "jql"
      ],
      "additionalProperties": false,
      "$schema": "http://json-schema.org/draft-07/schema#"
    }
  }
}

